/*
  Assignment outputs for the 29 test cases: 37433 outputs (1. Case 20044587: 924, 10. Case 27505812: 728, 11. Case 29366372: 1466, 12. Case 22251969: 349, 13. Case 22539296: 172, 14. Case 24244087: 418, 15. Case 26013492: 261, 16. Case 26228185: 705, 17. Case 26793610: 233, 18. Case 29802992: 315, 19. Case 22413744: 1247, 2. Case 20297618: 1397, 20. Case 22995465: 457, 21. Case 23473524: 1469, 22. Case 23488445: 436, 23. Case 23819016: 497, 24. Case 23831430: 5131, 25. Case 24181354: 3900, 26. Case 27617929: 2118, 27. Case 28662225: 2952, 28. Case 29279905: 1132, 29. Case 29974575: 2176, 3. Case 20626031: 1441, 4. Case 21255400: 1679, 5. Case 22342963: 1189, 6. Case 22580999: 945, 7. Case 24490144: 1262, 8. Case 25926192: 1413, 9. Case 27089790: 1021).
  Generated by models/hospital/outputs_to_sql.py (rules in its docstring). Run after assignments.sql.
  Each row is one instance of a product along one edge: the assignment (the spec, the person's job node, the person),
  the product edge from the step that makes it into a step receiving it in this project (DirectedEdges Type 1,
  AuthorisationId = the product as it flows), or its stub (TargetNodeId NULL) where no receiver was working then; the
  instance (Name); its source, the product as it flows, the receiver and the basis of receipt ('evidenced' by a linked
  record, or 'per the process') (Description); when it was recorded (CompletionDate). An instance to several receivers
  is several rows.
  Deadline and KMReferenceId NULL. Replaces the test cases' earlier outputs (@Reset = 1). If an assignment or stub
  can't be found, the script lists them and writes nothing. Set @Commit = 0 for a dry run.
*/
USE [3b30813b-994f-4bb1-a70f-9763e2b61154];
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Commit             bit              = 1;     -- 0 = dry run
DECLARE @Reset              bit              = 1;     -- 1 = replace the test cases' earlier outputs
DECLARE @OrganisationId     uniqueidentifier = 'DA8BA77A-AE36-43E0-A340-278B76345161';
DECLARE @AuthOrganisationId int              = 12;
DECLARE @ResultId           int              = 45;
DECLARE @CreatedBy          uniqueidentifier = 'A01AE24F-0301-4198-9036-8CC58F070B01';

DECLARE @rows TABLE (SpecName nvarchar(400), TeamName nvarchar(200), JobName nvarchar(200), ExecutorEmail nvarchar(256),
                     SrcJob nvarchar(200), SrcTeam nvarchar(200), SrcStep int,
                     DstJob nvarchar(200) NULL, DstTeam nvarchar(200) NULL, DstStep int NULL, Product nvarchar(400),
                     Name nvarchar(400), Description nvarchar(1000), CompletionDate datetime2,
                     SpecId uniqueidentifier NULL, NodeId int NULL, ExecutorGuid uniqueidentifier NULL, ExecutorInt int NULL,
                     StepNodeId int NULL, DstStepNodeId int NULL, DirectedEdgeId int NULL);

-- The spec, the assignment's job node and executor.
UPDATE r SET SpecId = s.Id FROM @rows r
JOIN [Results].dbo.Specs s ON s.Name COLLATE DATABASE_DEFAULT = r.SpecName COLLATE DATABASE_DEFAULT
                         AND s.ResultId = @ResultId AND s.OrganisationId = @OrganisationId;
DECLARE @jobNodes TABLE (Job nvarchar(200), Team nvarchar(200), NodeId int);
SELECT j.Job, j.Team, MIN(jn.Id)
FROM (SELECT JobName AS Job, TeamName AS Team FROM @rows UNION SELECT SrcJob, SrcTeam FROM @rows
      UNION SELECT DstJob, DstTeam FROM @rows WHERE DstJob IS NOT NULL) j
JOIN [Authorisation].dbo.SkillSets tk ON tk.Name COLLATE DATABASE_DEFAULT = j.Team COLLATE DATABASE_DEFAULT
                                     AND tk.NetworkId = 1 AND tk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes tn ON tn.SkillSetId = tk.Guid AND tn.NetworkId = 1 AND tn.OrganisationId = @OrganisationId
JOIN [Authorisation].dbo.SkillSets jk ON jk.Name COLLATE DATABASE_DEFAULT = j.Job COLLATE DATABASE_DEFAULT
                                     AND jk.NetworkId = 2 AND jk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes jn ON jn.SkillSetId = jk.Guid AND jn.NetworkId = 2 AND jn.ParentNodeId = tn.Id AND jn.OrganisationId = @OrganisationId
GROUP BY j.Job, j.Team;
UPDATE r SET NodeId = j.NodeId FROM @rows r JOIN @jobNodes j ON j.Job = r.JobName AND j.Team = r.TeamName;
UPDATE r SET ExecutorGuid = u.Guid, ExecutorInt = u.Id FROM @rows r
JOIN [Authorisation].dbo.Users u ON u.Email COLLATE DATABASE_DEFAULT = r.ExecutorEmail COLLATE DATABASE_DEFAULT
                                AND u.OrganisationId = @AuthOrganisationId;

-- The edge: the product from the making step into the receiving step, or its stub (no target) where none received it.
UPDATE r SET StepNodeId = sn.Id FROM @rows r
JOIN @jobNodes j ON j.Job = r.SrcJob AND j.Team = r.SrcTeam
JOIN dbo.Nodes sn ON sn.NetworkId = 3 AND sn.ParentNodeId = j.NodeId AND sn.HorizontalIndex = r.SrcStep
                 AND sn.OrganisationId = @OrganisationId;
UPDATE r SET DstStepNodeId = dn.Id FROM @rows r
JOIN @jobNodes j ON j.Job = r.DstJob AND j.Team = r.DstTeam
JOIN dbo.Nodes dn ON dn.NetworkId = 3 AND dn.ParentNodeId = j.NodeId AND dn.HorizontalIndex = r.DstStep
                 AND dn.OrganisationId = @OrganisationId;
UPDATE r SET DirectedEdgeId = e.Id FROM @rows r
JOIN [Authorisation].dbo.Products p ON p.Name COLLATE DATABASE_DEFAULT = r.Product COLLATE DATABASE_DEFAULT
                                   AND p.NetworkId = 2 AND p.OrganisationId = @AuthOrganisationId
JOIN dbo.DirectedEdges e ON e.SourceNodeId = r.StepNodeId AND e.Type = 1 AND e.AuthorisationId = p.Guid
                        AND ((r.DstStep IS NULL AND e.TargetNodeId IS NULL) OR e.TargetNodeId = r.DstStepNodeId);

-- ExecutorId and AssignmentId take a Guid or an Id, whichever their columns are.
DECLARE @byGuid bit = CASE WHEN (SELECT t.name FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                                 WHERE c.object_id = OBJECT_ID('dbo.Assignments') AND c.name = 'ExecutorId') = 'uniqueidentifier'
                           THEN 1 ELSE 0 END;
DECLARE @outByGuid bit = CASE WHEN (SELECT t.name FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                                    WHERE c.object_id = OBJECT_ID('dbo.AssignmentOutputs') AND c.name = 'AssignmentId') = 'uniqueidentifier'
                              THEN 1 ELSE 0 END;
IF OBJECT_ID('tempdb..#output_rows') IS NOT NULL DROP TABLE #output_rows;
SELECT * INTO #output_rows FROM @rows;
ALTER TABLE #output_rows ADD AssignmentKey nvarchar(50) NULL;
DECLARE @find nvarchar(max) = N'
UPDATE r SET AssignmentKey = CONVERT(nvarchar(50), ' + CASE WHEN @outByGuid = 1 THEN N'a.Guid' ELSE N'a.Id' END + N')
FROM #output_rows r JOIN dbo.Assignments a ON a.SpecId = r.SpecId AND a.NodeId = r.NodeId
 AND a.ExecutorId = ' + CASE WHEN @byGuid = 1 THEN N'r.ExecutorGuid' ELSE N'r.ExecutorInt' END + N';';
EXEC sp_executesql @find;

IF EXISTS (SELECT 1 FROM #output_rows WHERE AssignmentKey IS NULL OR DirectedEdgeId IS NULL)
BEGIN
    SELECT DISTINCT TOP (50) SpecName, JobName, TeamName, ExecutorEmail, SrcJob, SrcTeam, SrcStep, DstJob, DstTeam, DstStep,
           Product,
           CASE WHEN SpecId IS NULL THEN 'spec not found (run the test cases)'
                WHEN NodeId IS NULL OR ExecutorGuid IS NULL OR AssignmentKey IS NULL THEN 'assignment not found (run assignments.sql)'
                WHEN StepNodeId IS NULL OR (DstStep IS NOT NULL AND DstStepNodeId IS NULL) THEN 'step not found (run process.sql)'
                WHEN DstStep IS NULL THEN 'output stub not found (run process.sql)'
                ELSE 'product edge not found (run process.sql)' END AS Problem
    FROM #output_rows WHERE AssignmentKey IS NULL OR DirectedEdgeId IS NULL;
    DROP TABLE #output_rows;
    RAISERROR('Some assignments or output stubs could not be found (see grid): nothing written.', 16, 1);
    RETURN;
END

BEGIN TRANSACTION;

DECLARE @removed int = 0;
IF @Reset = 1
BEGIN
    DECLARE @clear nvarchar(max) = N'
    DELETE o FROM dbo.AssignmentOutputs o JOIN dbo.Assignments a ON o.AssignmentId = ' +
        CASE WHEN @outByGuid = 1 THEN N'a.Guid' ELSE N'a.Id' END + N'
    WHERE a.SpecId IN (SELECT DISTINCT SpecId FROM #output_rows);
    SELECT @removed = @@ROWCOUNT;';
    EXEC sp_executesql @clear, N'@removed int OUTPUT', @removed OUTPUT;
END

                                   CreationDate, ModificationDate, CreatedBy, ModifiedBy)
SELECT r.Name, r.Description, r.AssignmentKey, r.DirectedEdgeId, NULL, NULL, r.CompletionDate,
       r.CompletionDate, NULL, @CreatedBy, NULL
FROM #output_rows r;
DECLARE @added int = @@ROWCOUNT;

SELECT @removed AS OutputsRemoved, @added AS OutputsAdded;
SELECT SpecName, Product, COUNT(*) AS Outputs FROM #output_rows GROUP BY SpecName, Product ORDER BY SpecName, COUNT(*) DESC;
DROP TABLE #output_rows;

IF @Commit = 1 BEGIN COMMIT TRANSACTION;   PRINT 'Committed.'; END
ELSE           BEGIN ROLLBACK TRANSACTION; PRINT 'Dry run: rolled back.'; END
